<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useUserStore} from '@/stores/user'
import {sampleIdentities,sampleIdentity} from '@/api/modules/sampleManagement'
import type {SampleIdentity,SampleLabel,SamplePage} from '@/types/sampleManagement'
import PartnerWorkspace from '../PartnerWorkspace.vue'
import PartnerPhoto from '../PartnerPhoto.vue'
import PartnerFiles from '../PartnerFiles.vue'
import SampleLabelPrint from './SampleLabelPrint.vue'
import SampleShipments from './SampleShipments.vue'
import SampleBatchActionDialog from './SampleBatchActionDialog.vue'
import SampleColorCorrectionDialog from './SampleColorCorrectionDialog.vue'
import {ElMessage} from 'element-plus'
import {sampleDomains} from '@/utils/sampleDomains'
import {saveBlob} from '@/utils/file'
const route=useRoute(),router=useRouter(),user=useUserStore()
const legacy=computed(()=>!!(route.query.id||route.query.new||route.query.sourceType||route.query.projectId||route.query.modelProductId||route.query.productId||route.query.customerId||route.query.customerContext||route.query.supplierCode||route.query.view==='batches'))
const mode=computed(()=>route.query.view==='shipments'?'shipments':'identities'),domain=computed(()=>String(route.meta.sampleDomain||route.query.domain||''))
const data=ref<SamplePage<SampleIdentity>>(),detail=ref<SampleIdentity>(),keyword=ref(''),page=ref(1),loading=ref(false),error=ref(''),selected=ref(new Map<number,SampleIdentity>()),printOpen=ref(false),labels=ref<SampleLabel[]>([]),batchChoice=ref(false),pendingAction=ref('')
const bulkAction=ref<'loan'|'return'>(),bulkRows=ref<SampleIdentity[]>([]),colorEditing=ref(false)
const selectedOnPage=computed(()=>(data.value?.content||[]).filter(row=>selected.value.has(row.sampleIdentityId)).length)
const pageSelected=computed(()=>!!data.value?.content.length&&selectedOnPage.value===data.value.content.length)
function selectPage(checked:boolean){for(const row of data.value?.content||[])check(row,checked)}
function beginBulk(action:'loan'|'return'){bulkRows.value=[...selected.value.values()];bulkAction.value=action}
function sendSelected(){if(selected.value.size>100){ElMessage.warning('一次最多选择100种样品');return}void router.push({path:route.path,query:{view:'shipments',newShipment:'mexico_outbound',sampleIdentityIds:[...selected.value.keys()].join(',')}})}
async function bulkSaved(){bulkAction.value=undefined;selected.value=new Map();await load();if(detail.value)await loadDetail()}
async function colorSaved(value:SampleIdentity){selected.value.delete(Number(route.query.identityId));colorEditing.value=false;detail.value=value;await load();if(value.sampleIdentityId!==Number(route.query.identityId))void router.replace({path:route.path,query:{...route.query,identityId:value.sampleIdentityId}})}
const exporting=ref(false),exportError=ref('')
let epoch=0,detailEpoch=0,exportEpoch=0,disposed=false
const canWrite=computed(()=>user.hasPermission('samples:write'))
const canCorrectColor=computed(()=>canWrite.value&&(user.permissions.includes('*')||user.profile?.canMaintainEngineeringData===true))
const domainTitle=computed(()=>domain.value==='model'||domain.value==='research'||domain.value==='partner'?sampleDomains[domain.value]+'样品管理':'样品管理')
const receiptLabel=computed(()=>domain.value==='model'?'登记型号收样':domain.value==='research'?'登记研发收样':'其他来源收样')
const correctionColor=(data:Record<string,unknown>|undefined,key:string)=>String((data?.[key] as {colorName?:string})?.colorName||'未填写')
const quantity=(value:number|undefined)=>value==null?'—':new Intl.NumberFormat('zh-CN').format(value)
const positions=(row:SampleIdentity)=>(row.positions||row.balances.positions||[]).filter(p=>p.onhand>0)
const borrowedTo=(row:SampleIdentity)=>(row.loans||row.balances.loans||[]).filter(loan=>loan.outstanding>0).map(loan=>loan.person+' · '+loan.outstanding+' 件').join('；')||'接收人待核对'
const photo=(row:SampleIdentity)=>row.files?.find(f=>f.type?.startsWith('image/'))?.id
async function load(){if(legacy.value||mode.value!=='identities')return;const ticket=++epoch,auth=user.token;loading.value=true;error.value='';try{const next=await sampleIdentities({domain:domain.value||undefined,keyword:keyword.value.trim(),page:page.value,size:50});if(ticket===epoch&&auth===user.token){data.value=next;for(const row of next.content)if(selected.value.has(row.sampleIdentityId))selected.value.set(row.sampleIdentityId,row)}}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'读取样品失败，请重试'}finally{if(ticket===epoch)loading.value=false}}
async function loadDetail(){const id=Number(route.query.identityId);if(!id){detail.value=undefined;return}const ticket=++detailEpoch,auth=user.token;loading.value=true;error.value='';try{const value=await sampleIdentity(id);if(ticket===detailEpoch&&auth===user.token)detail.value=value}catch(e){if(ticket===detailEpoch&&auth===user.token)error.value=e instanceof Error?e.message:'读取样品详情失败'}finally{if(ticket===detailEpoch)loading.value=false}}
function showView(view:string){void router.push({path:route.path,query:{...(domain.value&&!route.meta.sampleDomain?{domain:domain.value}:{}),...(view==='identities'?{}:{view})}})}
function open(row:SampleIdentity){void router.push({path:route.path,query:{...route.query,identityId:row.sampleIdentityId}})}
function check(row:SampleIdentity,checked:boolean){if(checked)selected.value.set(row.sampleIdentityId,row);else selected.value.delete(row.sampleIdentityId)}
function labelRows(rows:SampleIdentity[]):SampleLabel[]{return rows.map(row=>({sampleIdentityId:row.sampleIdentityId,sampleCode:row.sampleCode,name:row.name,supplierName:row.supplierName,productName:row.productName,phoneName:row.phoneName,specName:row.specName,colorName:row.colorName,sampleVersion:row.sampleVersion}))}
function print(rows:SampleIdentity[]){labels.value=labelRows(rows);printOpen.value=true}
async function exportLabels(){
 if(disposed||exporting.value||loading.value||!selected.value.size||!user.token)return
 const ticket=++exportEpoch,auth=user.token,actor=user.profile?.userId,snapshot=labelRows([...selected.value.values()]),origin=window.location.origin,now=new Date()
 const current=()=>!disposed&&ticket===exportEpoch&&auth===user.token&&actor===user.profile?.userId
 const fileName=`样品标签-${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}.xlsx`
 exporting.value=true;exportError.value=''
 try{
  const {buildSampleLabelWorkbook}=await import('@/utils/sampleLabelExport')
  if(!current())return
  const blob=await buildSampleLabelWorkbook(snapshot,origin)
  if(current())saveBlob(blob,fileName)
 }catch(e){if(current())exportError.value=e instanceof Error?e.message:'标签导出失败，请重试'}finally{if(ticket===exportEpoch)exporting.value=false}
}
function openBatch(id:number,action=''){batchChoice.value=false;void router.push({path:route.path,query:{id,from:route.fullPath,...(action&&action!=='files'?{action}:{})}})}
function operate(action:string){if(!detail.value)return;pendingAction.value=action;if(detail.value.batches?.length===1)openBatch(detail.value.batches[0]!.id,action);else batchChoice.value=true}
function closeDetail(){const query={...route.query};delete query.identityId;void router.push({path:route.path,query})}
watch(()=>[route.path,route.query.view,route.query.id,route.query.new],()=>{++detailEpoch;detail.value=undefined;selected.value=new Map();page.value=1;void load()},{immediate:true})
watch(()=>route.query.identityId,()=>{++detailEpoch;detail.value=undefined;if(!legacy.value)void loadDetail()},{immediate:true})
watch(()=>user.token,()=>{bulkAction.value=undefined;colorEditing.value=false;++epoch;++detailEpoch;data.value=undefined;detail.value=undefined;selected.value=new Map();labels.value=[];printOpen.value=false;batchChoice.value=false;error.value=''})
watch(()=>[user.token,user.profile?.userId],()=>{++exportEpoch;exporting.value=false;exportError.value='';selected.value=new Map()},{flush:'sync'})
onBeforeUnmount(()=>{disposed=true;++epoch;++detailEpoch;++exportEpoch})
</script>
<template>
 <PartnerWorkspace v-if="legacy"/>
 <section v-else class="sample-management">
  <header class="sample-title"><h1>{{domainTitle}}</h1><nav><button :class="{active:mode==='identities'}" @click="showView('identities')">样品台账</button><button :class="{active:mode==='shipments'}" @click="showView('shipments')">寄样物流</button><button @click="showView('batches')">收样批次／原流转</button></nav><div class="top-actions"><el-button v-if="canWrite&&!['model','research'].includes(domain)" size="small" @click="router.push({path:'/partner-selections',query:{from:route.fullPath}})">从选品目录登记收样</el-button><el-button v-if="canWrite&&domain!=='partner'" size="small" @click="router.push({path:route.path,query:{new:'1',from:route.fullPath}})">{{receiptLabel}}</el-button></div></header>
  <SampleShipments v-if="mode==='shipments'" :domain="domain"/>
  <template v-else><div class="sample-filters"><el-input v-model="keyword" size="small" clearable placeholder="搜索样品码、产品、型号或规格" @keyup.enter="page=1;load()"/><el-button size="small" @click="page=1;load()">查询</el-button><el-button size="small" @click="load">刷新</el-button><el-checkbox :model-value="pageSelected" :indeterminate="selectedOnPage>0&&!pageSelected" aria-label="全选本页样品" @change="selectPage(Boolean($event))">全选本页</el-checkbox><template v-if="canWrite"><el-button size="small" :disabled="!selected.size" @click="sendSelected">批量发往墨西哥</el-button><el-button size="small" :disabled="!selected.size" @click="beginBulk('loan')">批量借出</el-button><el-button size="small" :disabled="!selected.size" @click="beginBulk('return')">批量归还</el-button></template><el-button v-if="selected.size" link size="small" @click="selected=new Map()">清空已选 {{selected.size}} 项</el-button><el-button size="small" type="primary" :disabled="!selected.size" @click="print([...selected.values()])">批量打印标签（{{selected.size}}）</el-button><el-button size="small" :loading="exporting" :disabled="!selected.size||loading||exporting" @click="exportLabels">批量导出标签（{{selected.size}}）</el-button><span>共 {{data?.totalElements||0}} 种样品</span></div><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">重试</el-button></el-alert>
  <el-alert v-if="exportError" :title="exportError" type="error" :closable="false"><el-button link :disabled="!selected.size||loading||exporting" @click="exportLabels">重试导出</el-button></el-alert>
  <div class="identity-table" role="table" aria-label="同物同码样品台账" v-loading="loading"><div class="identity-row identity-head" role="row"><span><el-checkbox :model-value="pageSelected" :indeterminate="selectedOnPage>0&&!pageSelected" aria-label="表头全选本页样品" @change="selectPage(Boolean($event))"/> 图片</span><span>样品码／产品</span><span>供应商</span><span>型号／颜色／版本</span><span>实物数量</span><span>当前去向</span><span>操作</span></div><div class="identity-body"><article v-for="row in data?.content" :key="row.sampleIdentityId" class="identity-row" role="row"><div class="identity-photo" role="cell"><el-checkbox :model-value="selected.has(row.sampleIdentityId)" :aria-label="'选择'+row.sampleCode" @change="check(row,Boolean($event))"/><PartnerPhoto v-if="photo(row)" :id="photo(row)!" :allow-retry="true"/></div><div role="cell"><button class="identity-link" @click="open(row)">{{row.sampleCode}}</button><strong>{{row.productName||row.name}}</strong></div><div role="cell" class="identity-supplier"><small class="field-label">供应商</small><span v-if="row.supplierName">{{row.supplierName}}</span></div><div role="cell"><small class="field-label">型号／颜色／版本</small><span>{{row.phoneName||row.specName||'待核对'}}</span><small>{{[row.colorName,row.sampleVersion].filter(Boolean).join(' · ')}}</small></div><div role="cell" class="identity-numbers"><span>在库 <b>{{quantity(row.balances.onhand)}}</b> · 可用 {{quantity(row.balances.available)}}</span><small>借出 {{quantity(row.balances.borrowed)}} · 在途 {{quantity(row.balances.inTransit)}}</small></div><div role="cell"><small class="field-label">当前去向</small><span v-for="p in positions(row)" :key="p.name" class="position-line">{{p.name}} · {{p.onhand}} 件</span><small v-if="!positions(row).length">暂无在库位置</small><small v-if="row.balances.borrowed">{{borrowedTo(row)}}</small></div><div class="identity-actions" role="cell"><el-button link size="small" type="primary" @click="open(row)">查看／办理</el-button><el-button link size="small" @click="print([row])">二维码标签</el-button></div></article><el-empty v-if="data&&!data.content.length" description="暂无样品；实际收到后从原来源登记收样"/></div></div><footer><span>同种样品同码累计；SP 收样批次保留在详情。</span><el-pagination v-model:current-page="page" :page-size="50" :total="data?.totalElements||0" :pager-count="5" layout="total,prev,pager,next" size="small" @current-change="load"/></footer></template>
  <el-drawer :model-value="!!route.query.identityId" :title="detail?detail.sampleCode+' · '+detail.name:'样品详情'" size="min(920px,96vw)" @close="closeDetail"><div v-loading="loading" class="identity-detail"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="detail"><div class="detail-actions"><el-button type="primary" size="small" @click="print([detail])">打印／补打二维码标签</el-button><template v-if="canWrite"><el-button v-if="detail.sourceType==='catalog'&&canCorrectColor" size="small" @click="colorEditing=true">更正颜色</el-button><el-button size="small" @click="operate('loan')">借出</el-button><el-button size="small" @click="operate('return')">归还</el-button><el-button size="small" @click="operate('move')">移动位置</el-button><el-button size="small" @click="router.push({path:route.path,query:{view:'shipments',newShipment:'mexico_outbound',sampleIdentityId:detail.sampleIdentityId}})">发往墨西哥</el-button></template></div><p v-if="detail.legacySampleCode">旧码 {{detail.legacySampleCode}} 已归入 {{detail.sampleCode}}；原收样和流转记录保留。</p><h3>{{detail.productName||detail.name}}</h3><p v-if="detail.supplierName">供应商：{{detail.supplierName}}</p><p>{{detail.phoneName||detail.specName}} · {{[detail.colorName,detail.sampleVersion].filter(Boolean).join(' · ')}}</p><section class="identity-files"><PartnerFiles kind="sample-identities" :id="detail.sampleIdentityId" :files="detail.files||[]" :model-value="[]" :can-write="false" :can-write-money="false" compact/><el-button v-if="canWrite" size="small" @click="operate('files')">上传到原收样批次</el-button></section><div class="identity-summary"><strong>在库 {{detail.balances.onhand}}</strong><span>可用 {{detail.balances.available}}</span><span>借出 {{detail.balances.borrowed}}</span><span>在途 {{quantity(detail.balances.inTransit)}}</span></div><h3>当前实物位置</h3><p v-for="p in positions(detail)" :key="p.name">{{p.name}} · 在库 {{p.onhand}} · 可用 {{p.available}} · 留样 {{p.retained}} · 损坏 {{p.damaged}}</p><p v-if="!positions(detail).length">当前没有在库实物。</p><h3>借出待还</h3><p v-for="loan in (detail.loans||detail.balances.loans||[]).filter(l=>l.outstanding>0)" :key="loan.id">{{loan.person}} · 待还 {{loan.outstanding}} · 预计 {{loan.due||'未记录'}}</p><template v-if="detail.events?.some(e=>e.action==='sample_color_correction')"><h3>颜色更正记录</h3><p v-for="event in detail.events.filter(e=>e.action==='sample_color_correction')" :key="event.id">{{correctionColor(event.data,'before')}} → {{correctionColor(event.data,'after')}} · {{event.operator}}<br/>{{event.data?.reason}}</p></template><h3>收样批次与原流转</h3><article v-for="batch in detail.batches||[]" :key="batch.id" class="batch-row"><span>{{batch.receivedDate||'日期待核对'}} · 实收 {{quantity(batch.receivedQty)}} · 在库 {{batch.balances.onhand}} · 借出 {{batch.balances.borrowed}}<small>内部批次 {{batch.code}}</small></span><el-button size="small" @click="openBatch(batch.id)">原记录／图片附件／更正</el-button></article></template></div></el-drawer>
  <el-dialog v-model="batchChoice" :title="pendingAction==='files'?'选择图片附件归属的原收样批次':'选择本次办理的原收样批次'" width="min(620px,96vw)" append-to-body><p>同一码可多次收样，借还和移位继续使用原批次数量。</p><div v-for="batch in detail?.batches||[]" :key="batch.id" class="batch-row"><span>{{batch.receivedDate}} · 在库 {{batch.balances.onhand}} · 可借 {{batch.balances.available}}<small>内部 {{batch.code}}</small></span><el-button type="primary" size="small" @click="openBatch(batch.id,pendingAction)">{{pendingAction==='files'?'进入本批附件':'办理本批'}}</el-button></div></el-dialog>
  <SampleBatchActionDialog v-if="bulkAction" :action="bulkAction" :samples="bulkRows" @close="bulkAction=undefined" @saved="bulkSaved"/><SampleColorCorrectionDialog v-if="colorEditing&&detail" :sample="detail" @close="colorEditing=false" @saved="colorSaved"/>
  <SampleLabelPrint v-model="printOpen" :samples="labels"/>
 </section>
</template>
<style scoped>.sample-management{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;container-type:inline-size;font-size:12px}.sample-title,.sample-filters,.top-actions,footer,.detail-actions,.identity-summary{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.sample-title h1{font-size:16px;margin:0;color:#223952}.sample-title nav{display:flex;gap:3px;margin-left:10px}.sample-title nav button{border:0;background:transparent;padding:5px 10px;font:inherit;color:#61768f;cursor:pointer}.sample-title nav button.active{color:#246fbe;border-bottom:2px solid #409eff;font-weight:600}.top-actions{margin-left:auto}.sample-filters .el-input{width:min(390px,100%)}.sample-filters>span{margin-left:auto;color:#76869b}.identity-table{flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column;background:white;border:1px solid #dfe7f0;border-radius:4px}.identity-body{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden}.identity-row{display:grid;grid-template-columns:80px minmax(140px,1.2fr) minmax(110px,1fr) minmax(160px,1.6fr) minmax(140px,1fr) minmax(140px,1.2fr) 112px;gap:9px;align-items:center;padding:4px 10px;min-height:44px;line-height:18px;border-bottom:1px solid #e6edf4}.identity-row>div{min-width:0;overflow-wrap:anywhere}.identity-row strong{display:block;color:#273d56;font-weight:600}.identity-row small{display:block;color:#73859b;font-size:12px}.identity-head{min-height:32px;background:#eff4fa;color:#516a87;font-size:13px;font-weight:600}.identity-photo{display:flex;align-items:center;gap:6px}.identity-photo :deep(.partner-photo){width:42px;height:42px}.identity-link{padding:0;border:0;background:transparent;font:inherit;color:#2471bf;font-weight:600;cursor:pointer}.position-line{display:block}.identity-actions{display:flex;gap:4px;flex-wrap:wrap}.identity-actions :deep(.el-button+.el-button){margin-left:0}.field-label{display:none!important}footer{font-size:12px;color:#76879a;justify-content:space-between}footer :deep(.el-pagination){max-width:100%;flex-wrap:wrap}.identity-detail{font-size:12px;line-height:1.7;overflow-wrap:anywhere}.identity-detail h3{font-size:14px;color:#2b435f;margin:18px 0 7px}.batch-row{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e1e9f2;min-width:0}.batch-row span{min-width:0;overflow-wrap:anywhere}.batch-row small{display:block;font-size:11px;color:#8190a4}.identity-summary{padding:10px;background:#f0f5fb;color:#395978}.sample-management :deep(.el-button--small),.sample-management :deep(.el-input__wrapper),.sample-management :deep(.el-select__wrapper){min-height:28px;font-size:12px}@container(max-width:1000px){.identity-head{display:none}.identity-row{grid-template-columns:60px repeat(2,minmax(0,1fr));gap:7px}.identity-row>div:nth-child(3),.identity-row>div:nth-child(4){grid-column:2/-1}.identity-row>div:nth-child(5){grid-column:2}.identity-row>div:nth-child(6){grid-column:3}.identity-actions{grid-column:2/-1}.field-label{display:block!important}.sample-title nav{margin-left:0}.top-actions{margin-left:0}}@container(max-width:520px){.identity-row{grid-template-columns:42px minmax(0,1fr)}.identity-row>div:nth-child(n+3){grid-column:2!important}.sample-title nav{flex-wrap:wrap}.sample-filters .el-input{width:100%}}
</style>
